#include "lang/lang_generator.h"

#include "common/cpp_string.h"

#include <QtCore/QDir>
#include <QtCore/QFile>

namespace codegen::lang {
namespace {

const auto kHeader = QByteArray(
	"// WARNING! All changes made in this file will be lost!\n"
	"// Generated by codegen_lang.\n");

} // namespace

QList<GeneratedFile> Generate(const Catalog &catalog) {
	const auto &entries = catalog.base.entries;

	auto allTags = QStringList();
	for (const auto &entry : entries) {
		for (const auto &tag : entry.tags) {
			if (!allTags.contains(tag)) {
				allTags.push_back(tag);
			}
		}
	}
	allTags.sort();

	const auto signature = [](const Entry &entry) {
		auto result = QByteArray("QString " + entry.key.toUtf8() + "(now_t");
		if (entry.plural) {
			result += ", lngtag_count, double count";
		}
		for (const auto &tag : entry.tags) {
			if (entry.plural && tag == QStringLiteral("count")) {
				continue;
			}
			result += ", lngtag_" + tag.toUtf8() + ", const QString &" + tag.toUtf8();
		}
		return result + ")";
	};

	auto header = kHeader;
	header += "#pragma once\n\n";
	header += "#include \"lang/lang_instance.h\"\n\n";
	header += "namespace Lang {\n\n";
	header += "enum class Key : ushort {\n";
	for (const auto &entry : entries) {
		header += "\t" + entry.key.toUtf8() + ",\n";
	}
	header += "};\n\n";
	header += "inline constexpr auto kKeysCount = "
		+ QByteArray::number(entries.size()) + ";\n\n";
	header += "} // namespace Lang\n\n";
	// Tags live in the global namespace: tr::lng_x(tr::now, lt_count, 5).
	for (const auto &tag : allTags) {
		header += "enum lngtag_" + tag.toUtf8() + " { lt_" + tag.toUtf8() + " };\n";
	}
	header += "\nnamespace tr {\n\n";
	for (const auto &entry : entries) {
		header += "[[nodiscard]] " + signature(entry) + ";\n";
	}
	header += "\n} // namespace tr\n";

	const auto literalOrNull = [](bool has, const QString &value) {
		return has ? common::CppUtf8Literal(value) : QByteArray("nullptr");
	};
	auto source = kHeader;
	source += "#include \"lang_auto.h\"\n\n";
	source += "namespace Lang::internal {\nnamespace {\n\n";
	source += "const KeyData Keys[] = {\n";
	for (const auto &entry : entries) {
		const auto &other = catalog.other.entries[
			catalog.other.indexByKey.value(entry.key)];
		source += "\t{ \"" + entry.key.toUtf8() + "\", "
			+ (entry.plural ? "true" : "false") + ",\n\t\t{ "
			+ common::CppUtf8Literal(entry.value) + ",\n\t\t"
			+ common::CppUtf8Literal(other.value) + " },\n\t\t{ "
			+ literalOrNull(entry.hasOne, entry.one) + ", "
			+ literalOrNull(other.hasOne, other.one) + " } },\n";
	}
	source += "};\n\n} // namespace\n\n";
	source += "Catalog GeneratedCatalog() {\n";
	source += "\treturn Catalog{ Keys, int(sizeof(Keys) / sizeof(Keys[0])) };\n";
	source += "}\n\n";
	source += "} // namespace Lang::internal\n\n";
	source += "namespace tr {\n\n";
	for (const auto &entry : entries) {
		source += signature(entry) + " {\n";
		const auto key = "Lang::Key::" + entry.key.toUtf8();
		auto extra = QStringList();
		for (const auto &tag : entry.tags) {
			if (!entry.plural || tag != QStringLiteral("count")) {
				extra.push_back(tag);
			}
		}
		const auto base = entry.plural
			? ("Lang::GetPlural(" + key + ", count)")
			: ("Lang::GetValue(" + key + ")");
		if (extra.isEmpty()) {
			source += "\treturn " + base + ";\n";
		} else {
			source += "\tauto result = " + base + ";\n";
			for (const auto &tag : extra) {
				source += "\tLang::internal::ReplaceTag(result, \""
					+ tag.toUtf8() + "\", " + tag.toUtf8() + ");\n";
			}
			source += "\treturn result;\n";
		}
		source += "}\n\n";
	}
	source += "} // namespace tr\n";

	return {
		GeneratedFile{ QStringLiteral("lang_auto.h"), header },
		GeneratedFile{ QStringLiteral("lang_auto.cpp"), source },
	};
}

bool WriteFiles(
		const QString &directory,
		const QList<GeneratedFile> &files,
		QString &error) {
	if (!QDir().mkpath(directory)) {
		error = QStringLiteral("could not create directory '%1'").arg(directory);
		return false;
	}
	for (const auto &generated : files) {
		const auto path = QDir(directory).filePath(generated.name);
		auto file = QFile(path);
		if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)
			|| file.write(generated.content) != generated.content.size()) {
			error = QStringLiteral("could not write '%1'").arg(path);
			return false;
		}
	}
	return true;
}

} // namespace codegen::lang
